/* =====================================================================
   GreenAds Global – homepage SECTIONS ONLY (no header / no footer)
   light-green theme switched to light-blue
   Single file: styles + images + markup + interactions are all in here.
   Usage:  import App from "./App"   (or use <App /> in main.jsx)
   ===================================================================== */

const mod = (i, n) => ((i % n) + n) % n
const prefersReduced = () =>
  typeof window !== "undefined" && window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches

/* ---------------------------------------------------------------------
   MORE CLIENT USE CASES – tabs + auto-playing slider (React state)
   --------------------------------------------------------------------- */
const CASE_TABS = [
  { id: "ga26-filter-all", filter: "All", label: "All use-cases" },
  { id: "ga26-filter-whatsapp", filter: "WhatsApp", label: "WhatsApp use-cases" },
  { id: "ga26-filter-rcs", filter: "RCS", label: "RCS use-cases" },
  { id: "ga26-filter-sms", filter: "SMS", label: "SMS use-cases" },
]
const PREFERRED = ["KSEB", "TVS Motors", "Lulu Group", "Kerala Police"]
const AUTOPLAY_MS = 4000

function lastSrc(srcset) {
  return srcset.split(",").pop().trim().split(" ")[0]
}

function CaseShowcase() {
  const [filter, setFilter] = useState("All")
  const [idx, setIdx] = useState(0)
  const [hover, setHover] = useState(false)
  const [tabVisible, setTabVisible] = useState(true)
  const [inView, setInView] = useState(true)
  const wrapRef = useRef(null)
  const tabRefs = useRef([])
  const touch = useRef(null)

  const list = useMemo(
    () =>
      filter === "All"
        ? PREFERRED.map((n) => CASES.find((c) => c.company === n)).filter(Boolean)
        : CASES.filter((c) => c.channel === filter),
    [filter]
  )
  const current = list[idx] || list[0]
  const activeTab = CASE_TABS.find((t) => t.filter === filter) || CASE_TABS[0]

  const go = useCallback((n) => setIdx(mod(n, list.length)), [list.length])

  // autoplay (restarts after every manual change; pauses on hover / hidden tab / off-screen)
  useEffect(() => {
    if (hover || !tabVisible || !inView || prefersReduced()) return
    const t = setTimeout(() => setIdx((i) => mod(i + 1, list.length)), AUTOPLAY_MS)
    return () => clearTimeout(t)
  }, [idx, filter, hover, tabVisible, inView, list.length])

  useEffect(() => {
    const vis = () => setTabVisible(!document.hidden)
    document.addEventListener("visibilitychange", vis)
    return () => document.removeEventListener("visibilitychange", vis)
  }, [])

  useEffect(() => {
    const el = wrapRef.current
    if (!el || !("IntersectionObserver" in window)) return
    const io = new IntersectionObserver(([e]) => setInView(e.isIntersecting), { threshold: 0.15 })
    io.observe(el)
    return () => io.disconnect()
  }, [])

  const pick = (i) => {
    setFilter(CASE_TABS[i].filter)
    setIdx(0)
  }
  const onTabKey = (e, i) => {
    let n
    if (e.key === "ArrowRight") n = mod(i + 1, CASE_TABS.length)
    else if (e.key === "ArrowLeft") n = mod(i - 1, CASE_TABS.length)
    else if (e.key === "Home") n = 0
    else if (e.key === "End") n = CASE_TABS.length - 1
    else if (e.key === "Enter" || e.key === " ") {
      e.preventDefault()
      pick(i)
      return
    } else return
    e.preventDefault()
    pick(n)
    tabRefs.current[n] && tabRefs.current[n].focus()
  }

  const onTouchStart = (e) => {
    const t = e.touches[0]
    touch.current = { x: t.clientX, y: t.clientY }
  }
  const onTouchEnd = (e) => {
    if (!touch.current) return
    const t = e.changedTouches[0]
    const dx = t.clientX - touch.current.x
    const dy = t.clientY - touch.current.y
    touch.current = null
    if (Math.abs(dx) > 50 && Math.abs(dx) > Math.abs(dy) * 1.4) go(idx + (dx < 0 ? 1 : -1))
  }

  return (
    <div className="ga26-case-box-wrap" ref={wrapRef}>
      <div aria-label="Filter client use cases" role="tablist" className="ga26-case-tabs">
        {CASE_TABS.map((t, i) => {
          const on = t.filter === filter
          return (
            <a
              key={t.id}
              id={t.id}
              ref={(el) => (tabRefs.current[i] = el)}
              type="button"
              role="tab"
              data-filter={t.filter}
              aria-selected={on}
              aria-controls="ga26-case-panel"
              href="#"
              className={"w-button" + (on ? " ga26-active" : "")}
              tabIndex={on ? 0 : -1}
              onClick={(e) => {
                e.preventDefault()
                pick(i)
              }}
              onKeyDown={(e) => onTabKey(e, i)}
            >
              {t.label}
            </a>
          )
        })}
      </div>

      <div
        id="ga26-case-panel"
        role="tabpanel"
        aria-roledescription="carousel"
        aria-labelledby={activeTab.id}
        data-autoplay-ms={AUTOPLAY_MS}
        className="ga26-case-box"
        data-current-company={current.company}
        onPointerEnter={(e) => {
          if (e.pointerType === "mouse") setHover(true)
        }}
        onPointerLeave={() => setHover(false)}
        onTouchStart={onTouchStart}
        onTouchEnd={onTouchEnd}
      >
        <span id="ga26-case-status" role="status" className="ga26-sr-only">
          {current.company}, {idx + 1} of {list.length}
        </span>

        {CASES.map((c, i) => {
          const shown = c === current
          return (
            <div
              key={c.company}
              className="ga26-case-slide"
              data-case-index={i}
              data-company={c.company}
              data-channel={c.channel}
              hidden={!shown}
              aria-hidden={!shown}
            >
              <div>
                <div>
                  <img src={c.logo} alt={c.logoAlt} className={c.logoCls} decoding="async" />
                  {c.tags.map((t, k) => (
                    <span key={k}>{t}</span>
                  ))}
                </div>
                <h3>{c.title}</h3>
                <p>{c.desc}</p>
                <a href={c.href} className="ga26-btn ga26-mint">
                  {c.btn}
                </a>
              </div>
              <div>
                <img
                  src={lastSrc(c.srcset)}
                  srcSet={c.srcset}
                  sizes={c.sizes}
                  alt={c.alt}
                  loading="eager"
                  decoding="async"
                />
              </div>
            </div>
          )
        })}

        <div className="ga26-case-nav">
          <a
            id="ga26-case-prev"
            type="button"
            aria-label="Previous use case"
            href="#"
            className="w-button"
            onClick={(e) => {
              e.preventDefault()
              go(idx - 1)
            }}
          >
            ‹
          </a>
          <a
            id="ga26-case-next"
            type="button"
            aria-label="Next use case"
            href="#"
            className="w-button"
            onClick={(e) => {
              e.preventDefault()
              go(idx + 1)
            }}
          >
            ›
          </a>
        </div>

        <div className="ga26-case-controls">
          <div aria-label="Choose a use case">
            {list.map((s, i) => (
              <button
                key={s.company}
                type="button"
                aria-label={"Show " + s.company}
                aria-current={i === idx}
                className={i === idx ? "ga26-active" : ""}
                onClick={() => go(i)}
              />
            ))}
          </div>
        </div>
      </div>
    </div>
  )
}


