/* ---------------------------------------------------------------------
   Behaviour for the static sections: journey player, Telinfy tabs,
   studio tabs, FAQ accordion (header / footer are NOT included)
   --------------------------------------------------------------------- */
function useInteractions(rootRef) {
  useEffect(() => {
    const root = rootRef.current
    if (!root) return
    const cleanups = []
    const on = (t, e, f, o) => {
      if (!t) return
      t.addEventListener(e, f, o)
      cleanups.push(() => t.removeEventListener(e, f, o))
    }
    const $ = (s) => root.querySelector(s)
    const $$ = (s) => [...root.querySelectorAll(s)]
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)")

    const mark = (tabs, i) =>
      tabs.forEach((t, n) => {
        const o = n === i
        t.classList.toggle("ga26-active", o)
        t.setAttribute("aria-selected", String(o))
        t.tabIndex = o ? 0 : -1
      })
    const keys = (tabs) =>
      tabs.forEach((t, i) =>
        on(t, "keydown", (e) => {
          let n
          if (e.key === "ArrowRight") n = mod(i + 1, tabs.length)
          else if (e.key === "ArrowLeft") n = mod(i - 1, tabs.length)
          else if (e.key === "Home") n = 0
          else if (e.key === "End") n = tabs.length - 1
          else if (e.key === "Enter" || e.key === " ") {
            e.preventDefault()
            t.click()
            return
          } else return
          e.preventDefault()
          tabs[n].click()
          tabs[n].focus()
        })
      )

    /* ---- customer journey player ---- */
    const jTabs = $$("[data-step]"),
      jSlides = $$("[data-journey-index]"),
      jPanel = $("#ga26-journey-panel")
    let step = 0,
      jTimer = 0,
      progress = null
    const stopProgress = () => {
      progress && progress.cancel()
      progress = null
      jTabs.forEach((t) => {
        const l = t.querySelector(".ga26-journey-progress")
        if (l) l.style.transform = "scaleX(0)"
      })
    }
    const journeyPlay = () => {
      clearTimeout(jTimer)
      stopProgress()
      if (!jTabs.length || document.hidden) return
      const line = jTabs[step].querySelector(".ga26-journey-progress")
      if (reduced.matches) {
        if (line) line.style.transform = "scaleX(1)"
        return
      }
      if (line && line.animate)
        progress = line.animate([{ transform: "scaleX(0)" }, { transform: "scaleX(1)" }], {
          duration: 4000,
          easing: "linear",
          fill: "forwards",
        })
      jTimer = setTimeout(() => showJourney(step + 1, true), 4000)
    }
    const showJourney = (i, fade) => {
      step = mod(i, jSlides.length)
      jSlides.forEach((s, n) => (s.hidden = n !== step))
      mark(jTabs, step)
      if (jPanel) {
        jPanel.setAttribute("aria-labelledby", jTabs[step].id)
        jPanel.dataset.currentStep = String(step)
      }
      if (fade && !reduced.matches)
        jSlides[step]
          .querySelectorAll(".ga26-journey-explain,.ga26-journey-visual")
          .forEach((el) => el.animate && el.animate([{ opacity: 0.15 }, { opacity: 1 }], { duration: 280, easing: "ease-out" }))
      journeyPlay()
    }
    if (jPanel && jSlides.length) {
      jTabs.forEach((t, i) =>
        on(t, "click", (e) => {
          e.preventDefault()
          showJourney(i, true)
        })
      )
      keys(jTabs)
      showJourney(0)
      cleanups.push(() => {
        clearTimeout(jTimer)
        progress && progress.cancel()
      })
    }

    /* ---- Meet Telinfy tabs ---- */
    const tTabs = $$("[data-tel]"),
      tPanel = $("#ga26-tel-panel"),
      tImgs = tPanel ? [...tPanel.querySelectorAll("img")] : []
    const showTel = (i) => {
      if (!tPanel || !tImgs[i]) return
      mark(tTabs, i)
      tImgs.forEach((im, n) => {
        im.hidden = n !== i
        im.setAttribute("aria-hidden", String(n !== i))
      })
      tPanel.setAttribute("aria-labelledby", tTabs[i].id)
      tPanel.dataset.currentTab = String(i)
      tPanel.dataset.ready = "true"
    }
    if (tPanel && tImgs.length) {
      tImgs.forEach((im, i) => {
        im.loading = "eager"
        im.decoding = "async"
        im.hidden = i !== 0
        im.setAttribute("aria-hidden", String(i !== 0))
        const pre = new Image()
        pre.src = im.currentSrc || im.src
      })
      tTabs.forEach((t, i) =>
        on(t, "click", (e) => {
          e.preventDefault()
          showTel(i)
        })
      )
      keys(tTabs)
      showTel(0)
    }

    /* ---- Studio tabs (APIs / MCP) ---- */
    const studio = $(".ga26-studio"),
      sTabs = $$("[data-studio]"),
      sPanels = $$("[data-studio-panel]")
    const studioShow = (name) => {
      if (studio) studio.dataset.studioActive = name
      sTabs.forEach((t) => {
        const o = t.dataset.studio === name
        t.classList.toggle("ga26-active", o)
        t.setAttribute("aria-pressed", String(o))
      })
      sPanels.forEach((p) => (p.hidden = p.dataset.studioPanel !== name))
    }
    sTabs.forEach((t) =>
      on(t, "click", (e) => {
        e.preventDefault()
        studioShow(t.dataset.studio)
      })
    )
    keys(sTabs)
    studioShow("apis")

    /* ---- FAQ: one open at a time ---- */
    const faqs = $$(".ga26-faq details")
    faqs.forEach((d) =>
      on(d, "toggle", () => {
        if (d.open) faqs.forEach((o) => o !== d && (o.open = false))
      })
    )

    const resync = () => {
      if (jSlides.length) journeyPlay()
    }
    on(document, "visibilitychange", resync)
    on(reduced, "change", resync)

    return () => {
      cleanups.forEach((f) => f())
    }
  }, [rootRef])
}

